export function initStackingCards(selector = '[data-exhuma-stacking-cards]', options = {}) {
  const elements = document.querySelectorAll(selector);
  const cleanups = [];

  function smoothstep(t) {
    const c = Math.max(0, Math.min(1, t));
    return c * c * (3 - 2 * c);
