    const measureRect = () => {
      const r = card.getBoundingClientRect();
      rect = { left: r.left, top: r.top, width: r.width, height: r.height };
    };

    const updateFrame = () => {
      if (disabled || isReducedMotion) {
        card.style.transform = '';
        if (glareEl) glareEl.style.opacity = '0';
        rafId = null;
        return;
