import React, { useRef } from 'react';
import {
  View,
  StyleSheet,
  PanResponder,
  Animated,
  type ViewProps,
  type LayoutChangeEvent,
} from 'react-native';

export interface TiltCardProps extends ViewProps {
  maxTilt?: number;
  perspective?: number;
  scale?: number;
  speed?: number;
  glare?: boolean;
  maxGlareOpacity?: number;
  reverse?: boolean;
  disabled?: boolean;
  axis?: 'all' | 'x' | 'y';
  children?: React.ReactNode;
}

export function TiltCard({
  maxTilt = 15,
  perspective = 1000,
  scale = 1.02,
  speed = 0.12,
  glare = true,
  maxGlareOpacity = 0.3,
  reverse = false,
  disabled = false,
  axis = 'all',
  children,
  style,
  ...props
}: TiltCardProps) {
  const dimensions = useRef({ width: 0, height: 0 }).current;
  const tiltX = useRef(new Animated.Value(0)).current;
  const tiltY = useRef(new Animated.Value(0)).current;
  const scaleAnim = useRef(new Animated.Value(1)).current;

  const onLayout = (e: LayoutChangeEvent) => {
    const { width, height } = e.nativeEvent.layout;
    dimensions.width = width;
    dimensions.height = height;
  };

  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => !disabled,
      onMoveShouldSetPanResponder: () => !disabled,
      onPanResponderGrant: () => {
        if (disabled) return;
        Animated.spring(scaleAnim, {
          toValue: scale,
          useNativeDriver: true,
          friction: 7,
          tension: 40,
        }).start();
      },
      onPanResponderMove: (evt) => {
        if (disabled || dimensions.width === 0 || dimensions.height === 0) return;
        const { locationX, locationY } = evt.nativeEvent;

        const normX = Math.max(-0.5, Math.min(0.5, locationX / dimensions.width - 0.5));
        const normY = Math.max(-0.5, Math.min(0.5, locationY / dimensions.height - 0.5));
        const sign = reverse ? -1 : 1;

        const targetRotX = normY * -maxTilt * sign;
        const targetRotY = normX * maxTilt * sign;

        Animated.spring(tiltX, {
          toValue: axis === 'y' ? 0 : targetRotX,
          useNativeDriver: true,
          friction: 6,
          tension: 50,
        }).start();

        Animated.spring(tiltY, {
          toValue: axis === 'x' ? 0 : targetRotY,
          useNativeDriver: true,
          friction: 6,
          tension: 50,
        }).start();
      },
      onPanResponderRelease: () => {
        Animated.parallel([
          Animated.spring(tiltX, {
            toValue: 0,
            useNativeDriver: true,
            friction: 7,
            tension: 40,
          }),
          Animated.spring(tiltY, {
            toValue: 0,
            useNativeDriver: true,
            friction: 7,
            tension: 40,
          }),
          Animated.spring(scaleAnim, {
            toValue: 1,
            useNativeDriver: true,
            friction: 7,
            tension: 40,
          }),
        ]).start();
      },
    })
  ).current;

  const rotateX = tiltX.interpolate({
    inputRange: [-maxTilt, maxTilt],
    outputRange: [`${-maxTilt}deg`, `${maxTilt}deg`],
  });

  const rotateY = tiltY.interpolate({
    inputRange: [-maxTilt, maxTilt],
    outputRange: [`${-maxTilt}deg`, `${maxTilt}deg`],
  });

  return (
    <Animated.View
      onLayout={onLayout}
      {...panResponder.panHandlers}
      style={[
        styles.container,
        style,
        {
          transform: [
            { perspective },
            { rotateX },
            { rotateY },
            { scale: scaleAnim },
          ],
        },
      ]}
      {...props}
    >
      {children}
    </Animated.View>
  );
}

const styles = StyleSheet.create({
  container: {
    overflow: 'hidden',
    borderRadius: 20,
  },
});

