import 'package:flutter/material.dart';

class ExhumaSpotlightCard extends StatefulWidget {
  final Widget child;
  final double radius;
  final Color color;
  final Color borderColor;
  final double opacity;
  final double spread;
  final String mode;
  final double smoothing;
  final bool disabled;

  const ExhumaSpotlightCard({
    super.key,
    required this.child,
    this.radius = 350.0,
    this.color = const Color(0xFF6366F1),
    this.borderColor = const Color(0xFF818CF8),
    this.opacity = 0.85,
    this.spread = 60.0,
    this.mode = 'both',
    this.smoothing = 0.2,
    this.disabled = false,
  });

  @override
  State<ExhumaSpotlightCard> createState() => _ExhumaSpotlightCardState();
}

class _ExhumaSpotlightCardState extends State<ExhumaSpotlightCard> {
  Offset? _spotlightPos;
  double _opacity = 0.0;

  void _onEnter(PointerEnterEvent event) {
    if (widget.disabled) return;
    setState(() {
      _spotlightPos = event.localPosition;
      _opacity = widget.opacity;
    });
  }

  void _onHover(PointerHoverEvent event) {
    if (widget.disabled) return;
    setState(() {
      _spotlightPos = event.localPosition;
      _opacity = widget.opacity;
    });
  }

  void _onExit(PointerExitEvent event) {
    setState(() {
      _opacity = 0.0;
    });
  }

  @override
  Widget build(BuildContext context) {
    final showGlow = widget.mode == 'both' || widget.mode == 'background';
    final showBorder = widget.mode == 'both' || widget.mode == 'border';

    return MouseRegion(
      onEnter: _onEnter,
      onHover: _onHover,
      onExit: _onExit,
      child: ClipRRect(
        borderRadius: BorderRadius.circular(20),
        child: Stack(
          children: [
            Container(
              decoration: BoxDecoration(
                color: const Color(0xE6171717),
                borderRadius: BorderRadius.circular(20),
                border: Border.all(
                  color: const Color(0x1AFFFFFF),
                  width: 1,
                ),
              ),
              child: widget.child,
            ),
            if (showGlow && _spotlightPos != null)
              Positioned.fill(
                child: IgnorePointer(
                  child: AnimatedOpacity(
                    duration: const Duration(milliseconds: 150),
                    opacity: _opacity,
                    child: CustomPaint(
                      painter: _SpotlightPainter(
                        center: _spotlightPos!,
                        radius: widget.radius,
                        color: widget.color,
                        spread: widget.spread,
                      ),
                    ),
                  ),
                ),
              ),
            if (showBorder && _spotlightPos != null)
              Positioned.fill(
                child: IgnorePointer(
                  child: AnimatedOpacity(
                    duration: const Duration(milliseconds: 150),
                    opacity: _opacity,
                    child: Container(
                      decoration: BoxDecoration(
                        borderRadius: BorderRadius.circular(20),
                        border: Border.all(
                          color: widget.borderColor,
                          width: 1.5,
                        ),
                      ),
                    ),
                  ),
                ),
              ),
          ],
        ),
      ),
    );
  }
}

class _SpotlightPainter extends CustomPainter {
  final Offset center;
  final double radius;
  final Color color;
  final double spread;

  _SpotlightPainter({
    required this.center,
    required this.radius,
    required this.color,
    required this.spread,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..shader = RadialGradient(
        center: Alignment(
          (center.dx / size.width) * 2.0 - 1.0,
          (center.dy / size.height) * 2.0 - 1.0,
        ),
        radius: radius / size.shortestSide,
        colors: [color, Colors.transparent],
        stops: [spread / 100.0, 1.0],
      ).createShader(Rect.fromLTWH(0, 0, size.width, size.height));

    canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height), paint);
  }

  @override
  bool shouldRepaint(covariant _SpotlightPainter oldDelegate) {
    return oldDelegate.center != center ||
        oldDelegate.radius != radius ||
        oldDelegate.color != color ||
        oldDelegate.spread != spread;
  }
}

